    private static string[] Rows(string values)
    {
        var result = values.Split('|');
        if (result.Length != Entries.Count) throw new InvalidOperationException("Invalid source relocation localization row.");
        return result;
    }

    internal static string Translate(string language, string key)
    {
        var text = Entries[key];
        if (language == "zh-Hans") return text.Chinese;
        if (language == "zh-Hant") return text.Traditional;
        return Translations.TryGetValue(language, out var values) ? values[Array.IndexOf(Keys, key)] : text.English;
    }

    internal static void AddTo(string language, Dictionary<string, string> resources)
    {
        foreach (var key in Entries.Keys) resources[key] = Translate(language, key);
    }
}
